('workout', 'rep73', 0, 'Repeaters 7:3', 'Strength-endurance classic. Six hangs a set with short rests, so the forearms never fully recover.', '{"de":{"name":"Repeaters 7:3","description":"Der Kraftausdauer-Klassiker. Sechs Hangs pro Satz mit kurzen Pausen, damit sich die Unterarme nie ganz erholen."},"fr":{"name":"Repeaters 7:3","description":"Le classique de la force-endurance. Six suspensions par série avec des repos courts, pour que les avant-bras ne récupèrent jamais complètement."},"es":{"name":"Repeaters 7:3","description":"El clásico de fuerza-resistencia. Seis suspensiones por serie con descansos cortos, para que los antebrazos nunca se recuperen del todo."}}', '{"kind":"hangboard","focus":"power_endurance","minutes":null,"targetRpe":null,"items":[{"grip":"half","doses":[{"sets":6,"reps":6,"onS":7,"offS":3,"setRestS":180}]}]}'),
('workout', 'max10', 1, 'Max hangs', 'Near-maximal load, very little volume, long rests. The staple for raw finger strength.', '{"de":{"name":"Max Hangs","description":"Fast maximale Last, sehr wenig Volumen, lange Pausen. Der Standard für reine Fingerkraft."},"fr":{"name":"Suspensions max","description":"Charge quasi maximale, très peu de volume, longs repos. La base pour la force de doigts pure."},"es":{"name":"Suspensiones máximas","description":"Carga casi máxima, muy poco volumen, descansos largos. Lo básico para la fuerza de dedos pura."}}', '{"kind":"hangboard","focus":"strength","minutes":null,"targetRpe":null,"items":[{"grip":"half","doses":[{"sets":5,"reps":1,"onS":10,"setRestS":180}]}]}'),
('workout', 'fingers-ab', 2, 'Fingers A/B', 'Two finger sessions that take turns by session: max hangs for strength, then repeaters for the pump on long problems. Whichever you did last, the other comes up next, even after a missed day.', '{"de":{"name":"Finger A/B","description":"Zwei Fingereinheiten, die sich abwechseln: Max Hangs für Kraft, dann Repeaters für die Ausdauer an langen Bouldern. Was du zuletzt gemacht hast, entscheidet, was als Nächstes kommt, auch nach einem ausgelassenen Tag."},"fr":{"name":"Doigts A/B","description":"Deux séances de doigts qui alternent d''une séance à l''autre : suspensions max pour la force, puis répétitions pour l''endurance sur les longs blocs. Celle que tu n''as pas faite la dernière fois vient ensuite, même après un jour manqué."},"es":{"name":"Dedos A/B","description":"Dos sesiones de dedos que se turnan de una sesión a otra: suspensiones máximas para la fuerza y repeticiones para la resistencia en bloques largos. La que no hiciste la última vez es la siguiente, aunque te saltes un día."}}', '{"kind":"hangboard","focus":null,"minutes":null,"targetRpe":8,"items":[{"grip":"half","doses":[{"sets":6,"reps":1,"onS":10,"setRestS":180},{"sets":3,"reps":6,"onS":7,"offS":3,"setRestS":180}]}]}'),
('workout', 'block', 3, 'Block pulls', 'Lift a loaded block off the floor. Heavy pinch work without a board, and easy to load precisely.', '{"de":{"name":"Block Pulls","description":"Einen beschwerten Block vom Boden heben. Schweres Pinch-Training ohne Board, und die Last lässt sich genau dosieren."},"fr":{"name":"Tirages au bloc","description":"Soulève un bloc lesté du sol. Du travail de pince lourd sans pan, et une charge facile à doser."},"es":{"name":"Tirones de bloque","description":"Levanta un bloque lastrado del suelo. Trabajo de pinza pesado sin plafón, y una carga fácil de ajustar con precisión."}}', '{"kind":"hangboard","focus":"strength","minutes":null,"targetRpe":null,"items":[{"grip":"pinch","doses":[{"sets":5,"reps":5,"setRestS":120}]}]}'),
('workout', 'density', 4, 'Density hangs', 'Long, easy hangs at low intensity. Good tendon stimulus that you can do often.', '{"de":{"name":"Density Hangs","description":"Lange, lockere Hangs mit niedriger Intensität. Guter Reiz für die Sehnen, den du oft machen kannst."},"fr":{"name":"Suspensions densité","description":"Suspensions longues et faciles, à faible intensité. Un bon stimulus pour les tendons, à faire souvent."},"es":{"name":"Suspensiones de densidad","description":"Suspensiones largas y suaves a baja intensidad. Buen estímulo para los tendones que puedes hacer a menudo."}}', '{"kind":"hangboard","focus":null,"minutes":null,"targetRpe":null,"items":[{"grip":"open","doses":[{"sets":4,"reps":1,"onS":30,"setRestS":60}]}]}'),
('workout', 'assist', 5, 'Assisted one-arm', 'Weight removed with a pulley. Alternate arms each set and remove less over time.', '{"de":{"name":"Einarmig mit Entlastung","description":"Gewicht über eine Umlenkrolle abgenommen. Wechsle in jedem Satz den Arm und nimm mit der Zeit weniger ab."},"fr":{"name":"Un bras assisté","description":"Poids retiré avec une poulie. Alterne les bras à chaque série et retire moins de poids au fil du temps."},"es":{"name":"Un brazo asistido","description":"Peso quitado con una polea. Alterna los brazos en cada serie y quita menos peso con el tiempo."}}', '{"kind":"hangboard","focus":"strength","minutes":null,"targetRpe":null,"items":[{"grip":"half","doses":[{"sets":6,"reps":1,"onS":10,"setRestS":120}]}]}'),
('workout', 'lowpull', 6, 'Light daily lifts', 'Many light lifts, most days of the week. Blood flow for tendons, not a hard workout.', '{"de":{"name":"Leichte tägliche Züge","description":"Viele leichte Züge an den meisten Tagen der Woche. Durchblutung für die Sehnen, kein hartes Training."},"fr":{"name":"Tirages légers quotidiens","description":"Beaucoup de tirages légers, la plupart des jours de la semaine. De la circulation pour les tendons, pas une séance dure."},"es":{"name":"Tirones ligeros diarios","description":"Muchos tirones ligeros, casi todos los días de la semana. Riego para los tendones, no un entreno duro."}}', '{"kind":"hangboard","focus":"recovery","minutes":null,"targetRpe":null,"items":[{"grip":"open","doses":[{"sets":3,"reps":10,"setRestS":90}]}]}'),
('workout', 'min-edge', 7, 'Min edge hangs', 'Bodyweight hangs on the smallest edge you can hold for ten seconds. Smaller edge over time, no added weight.', '{"de":{"name":"Hängen an der kleinsten Leiste","description":"Hängen mit Körpergewicht an der kleinsten Leiste, die du zehn Sekunden hältst. Mit der Zeit kleinere Leisten, ohne Zusatzgewicht."},"fr":{"name":"Suspensions sur réglette mini","description":"Suspensions au poids du corps sur la plus petite réglette que tu tiens dix secondes. Des réglettes plus petites avec le temps, sans lest."},"es":{"name":"Suspensiones en regleta mínima","description":"Suspensiones con tu peso en la regleta más pequeña que aguantes diez segundos. Regletas más pequeñas con el tiempo, sin lastre."}}', '{"kind":"hangboard","focus":"strength","minutes":null,"targetRpe":null,"items":[{"grip":"half","doses":[{"sets":5,"reps":1,"onS":10,"setRestS":180}]}]}'),
('workout', 'seven-53', 8, '7:53 hangs', 'Three heavy seven-second hangs a set with almost a minute between. Max-hang strength with more total time under load.', '{"de":{"name":"7:53 Hangs","description":"Drei schwere Hangs von sieben Sekunden pro Satz, mit fast einer Minute dazwischen. Maximalkraft mit mehr Zeit unter Last."},"fr":{"name":"Suspensions 7:53","description":"Trois suspensions lourdes de sept secondes par série, avec presque une minute entre chacune. La force des suspensions max, avec plus de temps sous charge."},"es":{"name":"Suspensiones 7:53","description":"Tres suspensiones pesadas de siete segundos por serie, con casi un minuto entre cada una. Fuerza de suspensiones máximas con más tiempo bajo carga."}}', '{"kind":"hangboard","focus":"strength","minutes":null,"targetRpe":null,"items":[{"grip":"half","doses":[{"sets":3,"reps":3,"onS":7,"offS":53,"setRestS":180}]}]}'),
('workout', 'climb-limit', 9, 'Limit bouldering', 'A few boulders at your limit, full rests, full effort on every go. Stop when the moves get sloppy.', '{"de":{"name":"Limit-Bouldern","description":"Ein paar Boulder an deinem Limit, volle Pausen, voller Einsatz bei jedem Versuch. Hör auf, wenn die Züge unsauber werden."},"fr":{"name":"Bloc à la limite","description":"Quelques blocs à ta limite, repos complets, engagement total à chaque essai. Arrête quand les mouvements se dégradent."},"es":{"name":"Bloque al límite","description":"Unos pocos bloques a tu límite, descansos completos, todo en cada intento. Para cuando los movimientos se ensucien."}}', '{"kind":"climbing","focus":"power","minutes":90,"targetRpe":9,"items":[{"exercise":"limitBouldering","doses":[{"sets":5,"setRestS":180}]}]}'),
('workout', 'climb-4x4', 10, '4x4s', 'Four boulders back to back, four times, with a few minutes'' rest between rounds.', '{"de":{"name":"4x4","description":"Vier Boulder direkt hintereinander, viermal, mit ein paar Minuten Pause zwischen den Runden."},"fr":{"name":"4x4","description":"Quatre blocs enchaînés, quatre fois, avec quelques minutes de repos entre les tours."},"es":{"name":"4x4","description":"Cuatro bloques seguidos, cuatro veces, con unos minutos de descanso entre rondas."}}', '{"kind":"climbing","focus":"power_endurance","minutes":60,"targetRpe":8,"items":[{"exercise":"fourByFours","doses":[{"sets":4,"reps":4,"setRestS":240}]}]}'),
('workout', 'climb-arc', 11, 'ARC', 'Easy climbing without stopping for 20 to 40 minutes. A light pump, never a burn.', '{"de":{"name":"ARC","description":"Leichtes Klettern ohne Pause, 20 bis 40 Minuten. Ein leichter Pump, nie ein Brennen."},"fr":{"name":"ARC","description":"De la grimpe facile sans s''arrêter pendant 20 à 40 minutes. Une légère conti, jamais de brûlure."},"es":{"name":"ARC","description":"Escalada fácil sin parar durante 20 a 40 minutos. Un bombeo ligero, nunca quemazón."}}', '{"kind":"climbing","focus":"endurance","minutes":45,"targetRpe":4,"items":[{"exercise":"arc","doses":[{"sets":2,"onS":1200,"setRestS":600}]}]}'),
('workout', 'strength-squat', 12, 'Back squat, alternating', 'Alternate five sets of five with three sets of ten. Each session does the next one, so a missed day just shifts it along.', '{"de":{"name":"Kniebeuge im Wechsel","description":"Wechselt fünf Sätze à fünf mit drei Sätzen à zehn ab. Jede Einheit macht die nächste, ein ausgelassener Tag verschiebt sie nur."},"fr":{"name":"Squat en alternance","description":"Alterne cinq séries de cinq et trois séries de dix. Chaque séance fait la suivante : un jour manqué la décale simplement."},"es":{"name":"Sentadilla alterna","description":"Alterna cinco series de cinco con tres series de diez. Cada sesión hace la siguiente, así que un día perdido solo la desplaza."}}', '{"kind":"strength","focus":"strength","minutes":45,"targetRpe":8,"items":[{"exercise":"backSquat","doses":[{"sets":5,"reps":5},{"sets":3,"reps":10}]}]}'),
('workout', 'strength-5x5', 13, '5x5 strength', 'Three big lifts, five sets of five. Add a little weight each week while every rep stays clean.', '{"de":{"name":"5x5 Kraft","description":"Drei große Übungen, fünf Sätze à fünf. Jede Woche etwas mehr Gewicht, solange jede Wiederholung sauber bleibt."},"fr":{"name":"Force 5x5","description":"Trois gros mouvements, cinq séries de cinq. Un peu plus lourd chaque semaine, tant que chaque répétition reste propre."},"es":{"name":"Fuerza 5x5","description":"Tres ejercicios grandes, cinco series de cinco. Un poco más de peso cada semana mientras cada repetición siga limpia."}}', '{"kind":"strength","focus":"strength","minutes":45,"targetRpe":8,"items":[{"exercise":"backSquat","doses":[{"sets":5,"reps":5}]},{"exercise":"benchPress","doses":[{"sets":5,"reps":5}]},{"exercise":"barbellRow","doses":[{"sets":5,"reps":5}]}]}'),
('workout', 'strength-antagonist', 14, 'Antagonist push', 'The pushing muscles climbing leaves behind, to keep shoulders balanced and healthy.', '{"de":{"name":"Antagonisten: Drücken","description":"Die Druckmuskeln, die beim Klettern zu kurz kommen, für ausgeglichene, gesunde Schultern."},"fr":{"name":"Antagonistes : poussée","description":"Les muscles de poussée que l''escalade délaisse, pour des épaules équilibrées et en bonne santé."},"es":{"name":"Antagonistas: empuje","description":"Los músculos de empuje que la escalada deja de lado, para unos hombros equilibrados y sanos."}}', '{"kind":"strength","focus":null,"minutes":30,"targetRpe":6,"items":[{"exercise":"pushUps","doses":[{"sets":3,"reps":15}]},{"exercise":"overheadPress","doses":[{"sets":3,"reps":8}]},{"exercise":"dips","doses":[{"sets":3,"reps":10}]},{"exercise":"externalRotation","doses":[{"sets":4,"reps":15}]}]}'),
('workout', 'strength-extensors', 15, 'Finger extensor routine', 'Trains the muscles that open the hand, to balance all the gripping. Light, and done often.', '{"de":{"name":"Fingerstrecker-Routine","description":"Trainiert die Muskeln, die die Hand öffnen, als Ausgleich zum vielen Greifen. Leicht und oft."},"fr":{"name":"Routine extenseurs des doigts","description":"Travaille les muscles qui ouvrent la main, pour compenser toutes les prises. Léger, et souvent."},"es":{"name":"Rutina de extensores de dedos","description":"Trabaja los músculos que abren la mano, para compensar tanto agarre. Ligero y a menudo."}}', '{"kind":"strength","focus":null,"minutes":15,"targetRpe":4,"items":[{"exercise":"bandExtensions","doses":[{"sets":3,"reps":20}]},{"exercise":"reverseWristCurls","doses":[{"sets":3,"reps":15}]},{"exercise":"riceBucket","doses":[{"sets":3,"onS":60}]}]}'),
('workout', 'mobility-hips', 16, 'Hip mobility flow', 'Opens the hips for high steps, drop knees and heel hooks.', '{"de":{"name":"Hüftmobilität","description":"Öffnet die Hüfte für hohe Tritte, Ägypter und Heelhooks."},"fr":{"name":"Mobilité des hanches","description":"Ouvre les hanches pour les pieds hauts, les lolottes et les crochets talon."},"es":{"name":"Movilidad de cadera","description":"Abre la cadera para pies altos, bavaresas y ganchos de talón."}}', '{"kind":"mobility","focus":"recovery","minutes":20,"targetRpe":3,"items":[{"exercise":"ninetyNinety","doses":[{"sets":1,"reps":10}]},{"exercise":"couchStretch","doses":[{"sets":1,"onS":60}]},{"exercise":"frogStretch","doses":[{"sets":1,"onS":90}]},{"exercise":"pigeon","doses":[{"sets":1,"onS":60}]},{"exercise":"hipFlexorLunge","doses":[{"sets":1,"onS":60}]},{"exercise":"deepSquat","doses":[{"sets":1,"onS":120}]}]}'),
('workout', 'yoga-climbers', 17, 'Climber''s yoga', 'Slow stretches for shoulders, back and hips on a rest day.', '{"de":{"name":"Yoga für Kletternde","description":"Langsame Dehnungen für Schultern, Rücken und Hüfte am Ruhetag."},"fr":{"name":"Yoga du grimpeur","description":"Des étirements lents pour les épaules, le dos et les hanches un jour de repos."},"es":{"name":"Yoga para escaladores","description":"Estiramientos lentos de hombros, espalda y cadera para un día de descanso."}}', '{"kind":"mobility","focus":"recovery","minutes":25,"targetRpe":2,"items":[{"exercise":"sunSalutation","doses":[{"sets":1,"reps":5}]},{"exercise":"downwardDog","doses":[{"sets":1,"onS":60}]},{"exercise":"threadNeedle","doses":[{"sets":1,"onS":60}]},{"exercise":"lizard","doses":[{"sets":1,"onS":60}]},{"exercise":"childsPose","doses":[{"sets":1,"onS":120}]}]}'),
('workout', 'run-tempo', 18, 'Tempo intervals', 'Three minutes hard, two minutes easy, five times. Hard means you could speak a few words.', '{"de":{"name":"Tempo-Intervalle","description":"Drei Minuten hart, zwei Minuten locker, fünfmal. Hart heißt: Du schaffst noch ein paar Worte."},"fr":{"name":"Fractionné tempo","description":"Trois minutes dur, deux minutes facile, cinq fois. Dur veut dire que tu peux encore dire quelques mots."},"es":{"name":"Intervalos de tempo","description":"Tres minutos fuerte, dos suave, cinco veces. Fuerte quiere decir que aún puedes decir unas palabras."}}', '{"kind":"other","focus":"conditioning","minutes":25,"targetRpe":7,"items":[{"step":"hard","doses":[{"sets":5,"onS":180}]},{"step":"easy","doses":[{"sets":5,"onS":120}]}]}'),
('workout', 'other-core', 19, 'Core circuit', 'Three rounds for the tension that keeps feet on steep ground.', '{"de":{"name":"Rumpfzirkel","description":"Drei Runden für die Spannung, die die Füße im Steilen hält."},"fr":{"name":"Circuit gainage","description":"Trois tours pour le gainage qui garde les pieds en place dans le dévers."},"es":{"name":"Circuito de core","description":"Tres rondas para la tensión que mantiene los pies en el desplome."}}', '{"kind":"other","focus":"strength","minutes":15,"targetRpe":6,"items":[{"exercise":"plank","doses":[{"sets":3,"onS":45,"offS":15}]},{"exercise":"hollowHold","doses":[{"sets":3,"onS":30,"offS":15}]},{"exercise":"kneeRaises","doses":[{"sets":3,"reps":10,"offS":60}]}]}')
